const b = ($json.body && typeof $json.body === 'object') ? $json.body : $json;
const id = String(b.item_id || '');
if (!/^[0-9a-f-]{36}$/i.test(id)) throw new Error('Brak item_id');
return [{ json: { item_id: id, reason: ['created', 'manual', 'scheduled'].includes(b.reason) ? b.reason : 'manual' } }];

const url = $('Wczytaj').first().json.url;
const m = /^https?:\/\/([a-z0-9.-]+\.[a-z]{2,})(:\d+)?(\/|$|\?)/i.exec(url || '');
if (!m) return [{ json: { ok: false, url, host: '', error: 'Niepoprawny adres strony.' } }];
if (m[2] && ![':80', ':443'].includes(m[2])) return [{ json: { ok: false, url, host: m[1], error: 'Niestandardowy port — nie pobieram.' } }];
return [{ json: { ok: true, url, host: m[1].toLowerCase() } }];

// Ochrona przed SSRF: adres podaje użytkownik, a pobiera nasz serwer. Wpuszczamy tylko http(s) na publiczne IP.
// Odpowiedzi DNS (DoH Cloudflare, A i AAAA) przychodzą z dwóch węzłów HTTP przed tym.
if (!$('Adres do pobrania').first().json.ok) return [{ json: $('Adres do pobrania').first().json }];
const url = $('Adres do pobrania').first().json.url;
const answers = [];
for (const src of [$('DNS A').first().json, $json]) for (const a of (src.Answer || [])) if (a.type === 1 || a.type === 28) answers.push(String(a.data));
const priv4 = (ip) => {
  const p = ip.split('.').map(Number); if (p.length !== 4 || p.some((x) => !(x >= 0 && x <= 255))) return true;
  return p[0] === 10 || p[0] === 127 || p[0] === 0 || (p[0] === 169 && p[1] === 254) || (p[0] === 172 && p[1] >= 16 && p[1] <= 31)
    || (p[0] === 192 && p[1] === 168) || (p[0] === 100 && p[1] >= 64 && p[1] <= 127) || p[0] >= 224;
};
const priv6 = (ip) => { const s = ip.toLowerCase(); return s === '::1' || s === '::' || /^(fc|fd|fe8|fe9|fea|feb)/.test(s) || s.startsWith('::ffff:'); };
const ips = answers.filter((a) => /^[\d.]+$/.test(a) || a.includes(':'));
if (!ips.length) return [{ json: { ok: false, url, error: 'Nie znalazłem tej domeny (DNS).' } }];
const bad = ips.filter((ip) => (ip.includes(':') ? priv6(ip) : priv4(ip)));
if (bad.length) return [{ json: { ok: false, url, error: 'Ten adres prowadzi do sieci wewnętrznej — nie pobieram go.' } }];
return [{ json: { ok: true, url, ips } }];

const s = Number($json.statusCode || 0); const loc = String(($json.headers || {}).location || '');
if (![301, 302, 303, 307, 308].includes(s) || !loc) return [{ json: { ...$json, redirect: false } }];
const base = $('Adres do pobrania').first().json.url; const origin = (base.match(/^https?:\/\/[^/?#]+/i) || [''])[0];
const next = /^https?:\/\//i.test(loc) ? loc : loc.startsWith('//') ? 'https:' + loc : loc.startsWith('/') ? origin + loc : origin + '/' + loc;
return [{ json: { redirect: true, next: next.slice(0, 500) } }];

